import {exportedInputs} from './evaluation-fixtures.mjs';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let config={enabled:false},running=false;
const current=()=>exportedInputs($('ai-split').value).cases.find(c=>c.id===$('ai-case').value);
function inputs(){const c=current();$('ai-inputs').innerHTML=`<h3>Intelligence question</h3><p>${esc(c.question)}</p>${c.documents.map(d=>`<article><h3>${esc(d.publisher)}</h3><p class="muted">${esc(d.id)} · ${esc(d.reportedAt)} · ${esc(d.language)} · Source group: ${esc(d.originGroup)}</p><blockquote class="source-excerpt">${esc(d.excerpt)}</blockquote></article>`).join('')}`;$('ai-ack').checked=false;$('ai-error').textContent='';$('ai-result').innerHTML='<p class="empty">No model draft for this selection.</p>';}
function cases(){const list=exportedInputs($('ai-split').value).cases;$('ai-case').innerHTML=list.map(c=>`<option value="${c.id}">${esc(c.question)}</option>`).join('');inputs();}
function availability(){ $('connection').textContent=config.notice||'API execution is unavailable here. Input inspection remains available.';$('ai-budget').textContent=config.enabled?`Configured model: ${config.model} · ${config.remaining} request attempts remain · At most ${config.maxOutputTokens} output tokens per request. Token limits are not a monetary budget.`:'No model call is made until API execution is explicitly configured.';$('ai-generate').disabled=running||!config.enabled||config.busy||config.remaining<1;}
async function status(){if(location.hostname!=='127.0.0.1'){config={enabled:false,notice:'Input inspection preview. Live API execution is available through the configured local runner.'};availability();return;}try{const r=await fetch('/api/ai/status');if(!r.ok)throw new Error();config=await r.json();}catch{config={enabled:false,notice:'API execution is unavailable. Input inspection remains available.'};}availability();}
function result(v,c){const row=v.report.rows.find(r=>r.caseId===c.id),execution=v.executions.find(r=>r.caseId===c.id);$('ai-result').innerHTML=`<h3>${esc(v.mode)}</h3><p class="notice">${esc(row.outcome)} · Exact citations do not establish semantic accuracy.</p>${execution.error?`<p class="error">${esc(execution.error)}</p>`:''}${row.error?`<p class="error">${esc(row.error)}</p>`:''}${row.structuralValid?row.output.abstention?`<h3>Abstention</h3><p>${esc(row.output.abstention)}</p>`:row.output.proposals.map(p=>`<article class="ai-draft"><h3>Attributed draft</h3><p>${esc(p.draftStatement)}</p><p class="muted">Limitations: ${esc(p.limitations)}</p>${p.citations.map(q=>{const d=c.documents.find(d=>d.id===q.documentId);return `<p class="small-label">${esc(d.publisher)} / ${esc(q.documentId)} / UTF-16 ${q.start}–${q.end}</p><blockquote class="source-excerpt">${esc(q.quote)}</blockquote>`;}).join('')}</article>`).join(''):''}<p class="muted">Evaluation includes all six cases in this set; unexecuted cases remain missing. This selected-case run does not pass the full suite. Assessment workspace unchanged.</p>`;}
$('ai-split').addEventListener('change',cases);$('ai-case').addEventListener('change',inputs);
$('ai-preview').addEventListener('click',()=>{$('ai-preview-text').value=JSON.stringify(current(),null,2);$('ai-preview-dialog').showModal();});$('ai-close-preview').addEventListener('click',()=>$('ai-preview-dialog').close());
$('ai-generate').addEventListener('click',async()=>{if(running)return;if(!$('ai-ack').checked){$('ai-error').textContent='Approve the single synthetic API request before generating a draft.';return;}const c=current(),split=$('ai-split').value;running=true;$('ai-case').disabled=$('ai-split').disabled=true;availability();$('ai-error').textContent='';try{const r=await fetch('/api/ai/analyze',{method:'POST',headers:{'Content-Type':'application/json','X-Ruthless-Request':'ai-console-v1'},body:JSON.stringify({split,caseId:c.id,allowApi:true})});const v=await r.json();if(!r.ok)throw new Error(v.error||'Analysis request failed.');result(v,c);}catch(e){$('ai-error').textContent=e.message;}finally{running=false;$('ai-case').disabled=$('ai-split').disabled=false;$('ai-ack').checked=false;await status();}});
cases();status();
